mapper.select:
SELECT COUNT(*)
FROM `order`
WHERE deleted = 0

    AND buyer_id = #{userId}


    AND seller_id = #{userId}


    AND status = #{status}

SELECT
DATE(create_time) AS date,
COUNT(*) AS value
FROM `order`
WHERE deleted = 0
AND create_time >= #{startDate}

    AND buyer_id = #{userId}


    AND seller_id = #{userId}

GROUP BY DATE(create_time)
ORDER BY date ASC
